import{_ as e,c as t,o,a2 as a}from"./chunks/framework.DAKqZgvW.js";const f=JSON.parse('{"title":"Helpful Tools","description":"","frontmatter":{},"headers":[],"relativePath":"tools.md","filePath":"tools.md"}'),s={name:"tools.md"},l=a('<h1 id="helpful-tools" tabindex="-1">Helpful Tools <a class="header-anchor" href="#helpful-tools" aria-label="Permalink to &quot;Helpful Tools&quot;">​</a></h1><p>In addition to the Modding API, there are many useful tools to help you creating mods.<br> Some of the popular ones include:<br></p><details class="details custom-block"><summary>Unity Explorer</summary><p>Essentialy like a unity editor built into the game, this tool allows you to view how the game is built from the editor side. You can find out object names, component values and all kinds of things that will help you. You can get its BepInEx version <a href="https://github.com/sinai-dev/UnityExplorer/releases" target="_blank" rel="noreferrer">here</a>.</p></details><details class="details custom-block"><summary>Assembly Publiczier</summary><p>This tool takes <code>Assembly-CSharp</code> and creates a publicized version of it, which means that all of its private fields, methods and more will become public. Cuphead hides many of the important fields and this tool allows you to use them without reflection. You can get it by following the instructions <a href="https://github.com/BepInEx/BepInEx.AssemblyPublicizer#readme" target="_blank" rel="noreferrer">here</a>.</p></details><details class="details custom-block"><summary>Unity Modding Template</summary><p>This is a unity project that contains audio clips, scripts, map and level templates, an asset bundle generator and more. You can use it as a project to make your asset bundles in and it&#39;s especially helpful when creating custom maps and levels, since you have everything you need already there. You can download this unity project <a href="https://drive.google.com/file/d/1gERIJdGg7x5gvWvJpsNUzsniijEc-J2x/view?usp=drive_link" target="_blank" rel="noreferrer">here</a>.</p></details>',5),i=[l];function r(n,d,c,u,h,p){return o(),t("div",null,i)}const _=e(s,[["render",r]]);export{f as __pageData,_ as default};
